def taken_under_the_position_now(apps, schema_editor):
    """
    O446: a document made before its lines' position was kept records its party's position as it stands
    (none for a tax-exempt party, as default_taxes reads it). Its lines were taken under some position
    nobody kept; the party's now is the best reading, and leaves every waiting draft posting as it did.
    """
    Profile = apps.get_model("accounting", "PartyTaxProfile")
    positions = {party: position for party, position, exempt in
                 Profile.objects.filter(fiscal_position__isnull=False)
                 .values_list("party_id", "fiscal_position_id", "tax_exempt") if not exempt}
    for name, party in MODELS:
        model = apps.get_model("sales", name)
        for party_id, position in positions.items():
            model._base_manager.filter(**{f"{party}_id": party_id}).update(taxes_taken_under_id=position)


